entries[160996] = { ["name"] = "Schwarzfelsschrapnelle", ["text"] = "Nahkampfreichweite\nSofort\nIhr tragt Schrapnelle, was Euch den Einsatz der Fähigkeit 'Schrapnellkanone' des Schwarzfelsgeschützturms ermöglicht.\n\nSchrapnellkanone\n35 Meter Reichweite\n\nSofort Trifft Gegner in einem kegelförmigen, vorwärts gerichteten Bereich und fügt Gegnern in der Nähe pro Sek. 8485573 Feuerschaden zu." }
entries[160997] = { ["name"] = "Schwarzfelsgranaten", ["text"] = "Nahkampfreichweite\nSofort\nTrägt Granaten und ermöglicht den Einsatz der Fähigkeit 'Schwarzfelsgranate'.\n\nSchwarzfelsgranate\n20 Meter Reichweite\n\nSofort Wirft eine Schwarzfelsgranate auf die anvisierte Position, fügt Gegnern in einem Umkreis von 3 Metern 11307099 Feuerschaden zu und stößt sie zurück." }
entries[160999] = { ["name"] = "Calamarescrepes", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRylakcrepes (5), Feurige Calamares (5), Nagrandpfeilkelch\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBeruf:\nKochkunst von Draenor (1)\nEntdeckung:\nKochrezepte von Draenor\n\nBenutzen: Stellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 kritischen Trefferwert.\n\nWenn Ihr dieses Gericht kostet, besteht eine Chance, dass Ihr das Rezept erlernt.\n35" }
entries[161000] = { ["name"] = "Gorgronder Fischsuppe", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGrollhufwürstchen (5), Sämige Schleichersuppe (5), Gorgrondfliegenfalle\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBeruf:\nKochkunst von Draenor (1)\nEntdeckung:\nKochrezepte von Draenor\n\nBenutzen: Stellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet für 1 Stunde 10 Vielseitigkeit.\n\nWenn Ihr dieses Gericht kostet, besteht eine Chance, dass Ihr das Rezept erlernt.\n35" }
entries[161001] = { ["name"] = "Sichelfischbrühe", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSichelfischfleisch (5)\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBeute von:\nWeltbeute von Draenor\nGegenstand:\nKochen auf Draenor leicht gemacht\n\nBenutzen: Stellt im Verlauf von 20 Sek. insgesamt ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n35" }
entries[161002] = { ["name"] = "Gegrillter Sichelfisch", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSichelfischfleisch (5)\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBeute von:\nWeltbeute von Draenor\nGegenstand:\nKochen auf Draenor leicht gemacht\n\nBenutzen: Stellt im Verlauf von 20 Sek. ( 2125 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n35" }
